candidates.pseudocode:
// newest-first; the pivot test is the measured SwingHigh port: at-or-beyond the S OLDER bars,
// STRICTLY beyond the S NEWER bars (EL_Swing_Probe). Confirmation lag is exactly S bars.
n = 0;
for (j = strength; j <= lookback - 1 && n < maxPivots; ++j) {
    isHi = true; isLo = true;
    for (k = j - strength; k < j; ++k) { if (!el_gt(high[j], high[k])) isHi = false; if (!el_lt(low[j], low[k])) isLo = false; }
    for (k = j + 1; k <= j + strength; ++k) { if (!el_ge(high[j], high[k])) isHi = false; if (!el_le(low[j], low[k])) isLo = false; }
    if (isHi) { t[n] = +1; v[n] = high[j]; b[n] = j; ++n; }
    if (isLo && n < maxPivots) { t[n] = -1; v[n] = low[j]; b[n] = j; ++n; }
}
// p[0] is the newest pivot; a rule needing m pivots checks n >= m (never a price sentinel)

pat = n >= 4 && t[3] == -1 && t[2] == +1 && t[1] == -1 && t[0] == +1
      && el_ge(v[1], v[3]) && el_le(v[1], v[2]) && el_ge(v[0], v[3]) && el_le(v[0], v[2]);
boxHi = v[0]; boxLo = v[1];
first = true;
for (i = 1; i < b[0]; ++i) if (el_gt(close[i], boxHi) || el_lt(close[i], boxLo)) first = false;
long = pat && first && el_gt(close[0], boxHi);
// short: the same pattern, el_lt(close[0], boxLo)

ok = n >= pivotCount + 1 && b[0] == strength && b[pivotCount] > b[1];
meanGap = (double)(b[pivotCount] - b[1]) / (pivotCount - 1);
lateGap = b[1] - b[0];
long = ok && t[0] == -1 && el_ge(lateGap, lateMultiple * meanGap);

// x[k], y[k]: bars-ago and price of swing-high occurrences k = 0..M-1 (high-side scan)
haveM = foundHighs >= M;
mx = mean(x); my = mean(y);
sxx = sum((x-mx)^2); sxy = sum((x-mx)*(y-my)); syy = sum((y-my)^2);   // centred: shift-invariant
slopeAgo = sxy / sxx;            // price per bar-ago; forward slope = -slopeAgo
r2 = sxy * sxy / (sxx * syy);    // guard syy > 0 and sxx > 0
lineAt(j) = my + slopeAgo * (j - mx);
qual = haveM && sxx > 0 && syy > 0 && el_gt(r2, minR2)
       && el_ge(slopeAgo, minSlopeAtr * atr(atrLength)) && x[0] <= maxAgeBars;
clean = true; for (i = 1; i < x[0]; ++i) if (el_gt(close[i], lineAt(i))) clean = false;
long = qual && clean && el_gt(close[0], lineAt(0));

// long side (mirror of the note's short):
long = el_lt(emaF, emaS) && el_lt(emaF, emaF[X]) && el_lt(emaS, emaS[X])
       && el_lt(emaS - emaF, emaS[X] - emaF[X]);

cnt = 0;
for (i = 0; i < X; ++i) if (el_ge(high[i], highest(high, Y)[i])) cnt = cnt + 1;   // bar i is the high of the Y bars ending at it
long = el_ge(cnt, fraction * X);

touch[i] = el_ge(high[i], bbUpper[i]);   // bbUpper = Average(close, N) + k * StdDev(close, N), population
// current episode: consecutive touch bars 0..e-1; previous episode: the next run of touch bars before a gap
prevHi = max high of the previous episode (within lookback);
curHiBefore = max high of bars 1..e-1 of the current episode;
long = touch[0] && havePrev && el_gt(high[0], prevHi) && !(e > 1 && el_gt(curHiBefore, prevHi));

T = most recent i in 1..L with el_ge(high[i], bbUpper[i]);
ok = haveT;
for (i = 1; i < T; ++i) if (el_le(low[i], bbLower[i]) || el_gt(close[i], high[T])) ok = false;
long = ok && !el_le(low[0], bbLower[0]) && el_gt(close[0], high[T]);

dLong  = average(close - ema, longWindow) / atr;
dShort = average(close - ema, shortWindow) / atr;
long = el_ge(dLong, minLongAtr) && el_le(absvalue(dShort), maxShortAtr);

big = 2 of last 2 bars: el_gt(close[i], open[i]) && el_ge(high[i] - low[i], K * atr);
ovl = min(high[0], high[1]) - max(low[0], low[1]);
long = big && el_le(ovl, F * min(high[0] - low[0], high[1] - low[1]));

if (el_le(low[0], ema) && el_ge(high[0], ema)) {
    if (el_gt(minlist(open[0], close[0]), ema)) upRun = upRun + 1; else upRun = 0;
    if (el_lt(maxlist(open[0], close[0]), ema)) dnRun = dnRun + 1; else dnRun = 0;
}
long = el_ge(upRun, touchCount);

// long side (mirror): search the newest qualifying w with Z <= w <= Z + maxWaitBars
isoHigh(w) = el_ge(high[w], highest(high, X)[w])
    && every bar j in w+1..w+Z and w-Z..w-1 has el_lt(high[j], high[w] - Y * atrAt(w));
clean = true; for (i = 1; i < w - Z; ++i) if (el_gt(close[i], high[w])) clean = false;   // first close beyond since confirmation
long = haveW && clean && el_gt(close[0], high[w]);

touch = el_le(low[0], ema) && el_ge(high[0], ema);
// persistent: gaps[] = bar counts between successive touches, newest-first; curGap = bars since last touch
long = touch && haveN && el_ge(curGap, K * meanOf(gaps, N)) && el_lt(high[1], ema[1]);

hh = highest(high, X)[1]; ll = lowest(low, X)[1];
out = maxlist(high[0] - hh, 0) + maxlist(ll - low[0], 0);
pass = el_ge(out, T * (high[0] - low[0]));   // product form: a zero-range bar cannot divide by zero

// y[0..M-1]: the M most recent swing lows (strength 1), newest-first
ok = foundLows >= M && el_le(max(y) - min(y), X * atr);
mu = mean(y); sd = sqrt(sum((y - mu)^2) / M);
ok = ok && el_le(sd, k * atr);
for (i = 1; i <= newestBarsAgo; ++i) if (el_lt(close[i], min(y) - margin * atr)) ok = false;
zoneLo = min(y); zoneHi = max(y);

// per side: centred least squares on (bars-ago, price) of occurrences 0..X-1
slopeHi = -sxyHi / sxxHi; slopeLo = -sxyLo / sxxLo;   // forward slope, price per bar
long = haveHi && haveLo && el_ge(slopeHi, s * atr) && el_ge(slopeLo, s * atr);

top = average(maxlist(open, close), N); bot = average(minlist(open, close), N);
mid = (top + bot) / 2; w = top - bot;
long = el_gt(close[0], mid + X * w);

up = 0; seen = 0;
for (i = 0; i < maxScanBars && seen < Y; ++i) {
    u = el_gt(high[i], highest(high, X)[i + 1]);
    d = el_lt(low[i], lowest(low, X)[i + 1]);
    if (u && !d) { up = up + 1; seen = seen + 1; }
    else if (d && !u) { seen = seen + 1; }
}
long = seen == Y && el_ge(up, F * Y);

ok = true;
for (i = 0; i < X; ++i) if (!el_gt(close[i], ma[i])) ok = false;
for (i = X; i < X + Y; ++i) if (!el_lt(close[i], ma[i])) ok = false;
long = ok;

// long side (mirror): latest swing high Hb (strength S) is the highest of the last Q swing highs;
// move = from the latest swing low before Hb (bar Lb) up to Hb
pbBars = Hb;   // bars 0..Hb-1 are the pullback
ok = haveH && haveL && pbBars >= S && pbBars <= maxPullbackBars;
for (i = 0; i < Hb; ++i) if (el_gt(high[i], vH) || el_lt(low[i], vL)) ok = false;
movMean = mean(high - low over bars Hb..Lb); pbMean = mean(high - low over bars 0..Hb-1);
long = ok && el_le(pbMean, R * movMean);

ok = foundHighs >= M && el_le(maxH - minH, tol * atr);
for (i = 1; i < oldestBarsAgo; ++i) if (el_gt(close[i], maxH + breakTol * atr)) ok = false;
long = ok && el_ge(close[0], maxH + Y * atr);

T = most recent i in 1..L with el_ge(high[i], highest(high, X)[i]) && el_ge(high[i], bbUpper[i]);
levelAt(i) = average(close, length)[i] - retraceDevs * stddev(close, length)[i];   // retraceDevs 0 = middle band, numDevs = lower band
level = levelAt(0);
first = true; for (i = 1; i < T; ++i) if (el_le(low[i], levelAt(i))) first = false;
long = haveT && first && el_le(low[0], level);

t = bar of highest(high, maxRun + maxPullback) in 1..; H = high[t];
run: s = t; while (s + 1 <= t + maxRun - 1 && el_gt(close[s + 1], open[s + 1])) s = s + 1;   // requires el_gt(close[t], open[t])
height = H - open[s];
breakaway = (s - t + 1 >= minRunBars) || el_ge(height, A * atr);
pb = t - 1; ok = pb >= minPullback && pb <= maxPullback;
for (i = 1; i < t; ++i) if (el_ge(high[i], H) || el_lt(low[i], H - f * height)) ok = false;
long = breakaway && ok && el_gt(close[0], H);

// long mirror; a > b >= 1 (bars ago)
sig1(a) = el_le(low[a], lowest(low, X)[a]) && no bar in 0..a-1 has el_lt(low[i], low[a]);
sig2(b) = a - b >= 1 && a - b <= X && el_ge(high[b], highest(high, X)[b]) && no bar in 0..b-1 has el_gt(high[i], high[b]);
zoneTop = low[b] + Y * (high[b] - low[b]);
first = no close in 1..b-1 inside [low[b], zoneTop];
long = sig1 && sig2 && first && el_le(close[0], zoneTop) && el_ge(close[0], low[b]);

// long as written: bear bar at offset W
midW = (high[W] + low[W]) / 2;
strong = el_lt(close[W], open[W]) && el_ge(open[W] - close[W], F * (high[W] - low[W])) && el_ge(high[W] - low[W], K * atrAt(W));
clean = true; for (i = 0; i < W; ++i) if (el_ge(high[i], midW)) clean = false;
long = strong && clean;

// long mirror
top = highest(high, N)[1]; bot = lowest(low, N)[1]; mid = (top + bot) / 2;
long = el_lt(low[0], bot) && el_gt(high[0], mid) && el_ge(high[0] - low[0], minRangeAtr * atr);

nv = 0;
for (i = M; i <= N; ++i) {
    if (el_le(low[i], close[0]) && el_ge(high[i], close[0])) {
        nv = nv + 1;
        // accumulate per rule: upper/lower wick hit, in-body hit, adx[i], high[i]-low[i], ticks[i], forward move
    }
}
enough = nv >= minVisits;

// long (mirror): lower-wick visits
if (visit && el_lt(close[0], minlist(open[i], close[i]))) lw = lw + 1;
long = enough && el_ge(lw, F * nv);
